async function addPhotos(files,replace=-1){for(const file of files.slice(0,replace>=0?1:Math.max(0,5-photos.length))){if(!file.type.startsWith('image/')||file.size>25000000){toast('请选择 25MB 以内的照片');continue}await new Promise(resolve=>{const u=URL.createObjectURL(file),im=new Image();im.onload=()=>{const c=document.createElement('canvas'),k=Math.min(1,1400/Math.max(im.width,im.height));c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);const p={image:c,data:c.toDataURL('image/jpeg',.85),crop:{zoom:1,x:.5,y:.5}};if(replace>=0)photos[replace]=p;else photos.push(p);URL.revokeObjectURL(u);resolve()};im.onerror=()=>{URL.revokeObjectURL(u);toast('这张照片未能读取');resolve()};im.src=u})}syncPhotos();paperChanged();toast('照片已加入，轻点照片可编辑；最多五张')}
