function basePhotoRects(){const b=sheetBounds(),n=photos.length;if(!n)return[];const mode=$('photoMode').value,rect=(x,y,w,h)=>({x:x*b.w,y:y*b.h,w:w*b.w,h:h*b.h});if(n===1)return[photoLayout().image];if(mode.startsWith('hero')){const count=Math.min(n-1,+mode.slice(4)||n-1),out=[rect(.06,.08,.88,.42)],gap=.025,w=(.88-(count-1)*gap)/count;for(let i=0;i<count;i++)out.push(rect(.06+i*(w+gap),.53,w,.23));for(let i=count+1;i<n;i++)out.push(rect(.06+(i-count-1)*.23,.79,.21,.15));return out}if(mode==='asym')return[[.06,.06,.55,.40],[.64,.16,.30,.25],[.12,.50,.38,.28],[.53,.45,.41,.37],[.23,.83,.55,.12]].slice(0,n).map(x=>rect(...x));const cols=n===2?2:n===3?3:2,rows=Math.ceil(n/cols),gap=.025,w=(.88-gap*(cols-1))/cols,h=(.75-gap*(rows-1))/rows;return photos.map((_,i)=>rect(.06+(i%cols)*(w+gap),.07+Math.floor(i/cols)*(h+gap),w,h))}
